# owner: platform
"""Contact sheet for substitute teachers."""

def _cells(student):
    if not student.email:
        raise ValueError(
            f"no email for {student.display_name}"
        )
    return (
        student.display_name,
        student.section,
        student.email
    )

def _line(cells, widths):
    padded = (c.ljust(w) for c, w in zip(cells, widths))
    return "  ".join(padded).rstrip()

# ---
def contact_rows(students):
    if not students:
        raise ValueError("no students given")
    ordered = sorted(students, key=lambda s: s.display_name)
    rows = [_cells(s) for s in ordered]
    widths = [max(map(len, col)) for col in zip(*rows)]
    return [_line(row, widths) for row in rows]
